```
// Cilium/XDP program (stripped)
__section("xdp") int lb(struct xdp_md *ctx) {
    void *data_end = (void *)(long)ctx->data_end;
    struct iphdr *ip = ctx->data + sizeof(struct ethhdr);
    if (ip + 1 > data_end) return XDP_DROP;

    __u32 vip = 0x0A000064;          // 10.0.0.100
    if (ip->daddr != vip) return XDP_PASS;

    __u32 backend = backends[hash % BACKEND_COUNT];
    ip->daddr = backend;
    return XDP_TX;
}
